import {
  ACTION_TAGS,
  actionLabel,
  actionTakesAmount,
  handRankLabel,
  hasActionLabels,
} from "./rank-labels";

describe("handRankLabel", () => {
  it("covers every tag to_string(HandRank) can emit", () => {
    // texasholdem_rank.cpp — a tag missing here would show up as a title-cased
    // enum name in the middle of a result card.
    const tags = [
      "HIGH_CARD",
      "ONE_PAIR",
      "TWO_PAIR",
      "THREE_OF_KIND",
      "STRAIGHT",
      "FLUSH",
      "FULL_HOUSE",
      "FOUR_OF_KIND",
      "STRAIGHT_FLUSH",
      "ROYAL_FLUSH",
    ];
    for (const tag of tags) {
      expect(handRankLabel(tag, "TH")).not.toBe(tag);
      expect(handRankLabel(tag, "TH")).toMatch(/^[A-Z]/);
    }
    expect(handRankLabel("FULL_HOUSE", "TH")).toBe("Full house");
  });

  it("covers every tag to_string(ZhaJinHuaHandType) can emit", () => {
    // zhajinhua_rank.cpp
    const tags = [
      "HIGH_CARD",
      "PAIR",
      "STRAIGHT",
      "FLUSH",
      "STRAIGHT_FLUSH",
      "THREE_OF_KIND",
      "SPECIAL_235",
    ];
    for (const tag of tags) {
      expect(handRankLabel(tag, "ZJH")).not.toBe(tag);
    }
    expect(handRankLabel("SPECIAL_235", "ZJH")).toBe("2-3-5");
  });

  it("returns nothing for the empty tag a foldout hand carries", () => {
    expect(handRankLabel("", "TH")).toBe("");
  });

  it("title-cases a tag it does not know rather than dropping it", () => {
    expect(handRankLabel("FIVE_OF_KIND", "TH")).toBe("Five of kind");
  });
});

describe("actionLabel", () => {
  it("reads as a sentence with the actor in front", () => {
    expect(actionLabel("RAISE")).toBe("raises to");
    expect(actionLabel("FOLD")).toBe("folds");
    expect(actionLabel("ALLIN")).toBe("is all in");
  });

  it("agrees with a second-person subject", () => {
    // The log calls the local player "You", so a third-person verb produces
    // "You calls".
    expect(actionLabel("CALL", true)).toBe("call");
    expect(actionLabel("RAISE", true)).toBe("raise to");
    expect(actionLabel("ALLIN", true)).toBe("are all in");
  });

  it("has both persons for every tag the gamecore reports", () => {
    // The fallback lowercases the tag, which reads fine for "fold" and wrong
    // for "raise" — so a missing entry would only show up on some moves.
    for (const tag of ACTION_TAGS) {
      expect(hasActionLabels(tag)).toBe(true);
    }
  });

  it("only pairs an amount with the verbs that take one", () => {
    // "folds 0" is how a log announces that it was generated by a machine.
    expect(actionTakesAmount("BET")).toBe(true);
    expect(actionTakesAmount("RAISE")).toBe(true);
    expect(actionTakesAmount("CALL")).toBe(true);
    for (const tag of ["FOLD", "CHECK", "ALLIN", "LOOK", "COMPARE"]) {
      expect(actionTakesAmount(tag)).toBe(false);
    }
  });
});
